"""Checkpoints generated by playing the original game from a local seed."""

from dataclasses import dataclass
from pathlib import Path

from .adapter import execute, observe


@dataclass(frozen=True)
class Scenario:
    goal: str
    budget: int
    script: tuple


SCENARIOS = {
    "exit": Scenario("Leave the current screen through the trail at the top edge.", 12, ("up",) * 5),
    "approach": Scenario("Walk up to the nearby monkey directly in front of Link. Stop within talking range.", 12, ("up",) * 3),
    "dialogue": Scenario("Talk to the monkey Link is facing and advance the first page of its dialogue.", 16,
                         ("interact", "wait", "interact", "wait", "interact")),
}


def achieved(name, observation, events):
    if name == "exit":
        return observation.room == "00:7a"
    if name == "dialogue":
        return "dialogue_opened" in events and any(
            event in ("dialogue_advanced", "dialogue_closed") for event in events
        )
    if observation.room != "00:5a" or observation.mode != "playing":
        return False
    return observation.facing == "up" and any(
        entity["slot"] == 8 and entity["kind"] == "monkey"
        and abs(entity["x"] - observation.x) <= 8
        and 0 < observation.y - entity["y"] <= 12
        for entity in observation.entities
    )


def prepare(pyboy, directory: Path):
    """Derive three checkpoints with controller inputs and no WRAM writes."""
    start = observe(pyboy)
    if (start.mode, start.room, start.x, start.y) != ("playing", "00:8a", 124, 56):
        raise ValueError("Checkpoint inicial precisa estar em 00:8a, XY 124,56, em modo playing")

    def capture(name):
        directory.mkdir(parents=True, exist_ok=True)
        with (directory / f"{name}.state").open("wb") as file:
            pyboy.save_state(file)

    capture("exit")
    for action in ("up",) * 14 + ("left",) * 4 + ("up",):
        execute(pyboy, action)

    # Skip through the game's introductory Impa cutscene with normal buttons.
    for _ in range(240):
        obs = observe(pyboy)
        if obs.room == "00:6a" and obs.mode == "playing":
            break
        action = "interact" if obs.mode == "dialogue" else "wait"
        execute(pyboy, action)
    else:
        raise RuntimeError("A cena de Impa não terminou no orçamento de preparação")

    for _ in range(6):
        execute(pyboy, "up")
    obs = observe(pyboy)
    if obs.room != "00:5a" or not any(
        entity["slot"] == 8 and entity["kind"] == "monkey" for entity in obs.entities
    ):
        raise RuntimeError("O macaco esperado não apareceu em 00:5a")
    capture("approach")

    for action in SCENARIOS["approach"].script:
        obs, _, _ = execute(pyboy, action)
    if not achieved("approach", obs, ()):
        raise RuntimeError("O script não chegou à posição esperada para conversar")
    capture("dialogue")
